{
 "rules": [
  {
   "rule_id": "KBMY-S2-R01-01",
   "status": "OK",
   "label": "가입 대상 연령 및 명의",
   "source": {
    "quote": "만 14세 이상의 실명의 개인 (공동명의 불가)"
   },
   "condition": {
    "and": [
     {
      ">=": [
       {
        "var": "customer.age"
       },
       14
      ]
     },
     {
      "==": [
       {
        "var": "customer.holder_type"
       },
       "INDIVIDUAL"
      ]
     }
    ]
   },
   "effect": {
    "type": "DISQUALIFY"
   }
  },
  {
   "rule_id": "KBMY-S2-R01-02",
   "status": "OK",
   "label": "공동명의 가입 불가",
   "source": {
    "quote": "공동명의 불가"
   },
   "condition": {
    "==": [
     {
      "var": "customer.holder_type"
     },
     "JOINT"
    ]
   },
   "effect": {
    "type": "DISQUALIFY"
   }
  },
  {
   "rule_id": "KBMY-S2-R01-03",
   "status": "OK",
   "label": "최대 가입 계좌 수 제한",
   "source": {
    "quote": "자유적립식 예금은 1인 최대 5계좌까지 가입 가능합니다."
   },
   "condition": {
    ">": [
     {
      "count_distinct_months": {
       "event": "DEPOSIT",
       "within": {
        "month_range": {
         "from": {
          "anchor": "contract.reference_date",
          "offset_months": -120,
          "day": "first"
         },
         "to": {
          "anchor": "contract.reference_date",
          "day": "last"
         }
        }
       }
      }
     },
     5
    ]
   },
   "effect": {
    "type": "DISQUALIFY"
   }
  }
 ]
}
```

